'use strict';
const projects = {
  realestate: {
    category:'FREELANCE / DEPLOYED OPERATIONS AUTOMATION',
    title:'Real Estate Operations Engine',
    subtitle:'Connecting leasing, applicant processing, rent reporting, signed agreements, and team workflows.',
    problem:'Property operations were spread across Buildium, Jira, PandaDoc, and Google Workspace. Relational records, lease deadlines, contract status, and outstanding balances had to be reconciled across disconnected tools.',
    approach:'Designed and deployed a Google Apps Script integration layer using REST APIs and a central Google Sheets operations hub. Batched data fetching and in-memory relationship mapping prepare consistent records for downstream workflows, while scheduled synchronization and document polling keep operational views up to date.',
    details:['Synced ERP records into a Google Workspace operations hub for leasing, applicants, and overdue rent.','Connected one-click agreement dispatch, signature tracking, signed PDF archival, and task updates.'],
    metric:'Leasing, contracts, rent reporting, and team tasks connected.',
    architecture:"<figure class=\"exact-architecture\"><figcaption>Freelance operations architecture</figcaption><a href=\"real-estate-architecture.svg\" aria-label=\"Open the full-size real estate architecture diagram\"><img src=\"real-estate-architecture.svg\" alt=\"Buildium feeds three Google Workspace modules. Leasing and Units syncs directly to Jira. Applicant Pipeline sends agreements through PandaDoc to Google Drive, then attaches signed file links to the same Jira workflow.\"></a><a class=\"text-link\" href=\"real-estate-architecture.svg\">Open full-size diagram \u2197</a></figure>",
    stack:['Google Apps Script','JavaScript / ES6+','REST APIs','JSON','Buildium','Jira Cloud','PandaDoc','Google Sheets','Google Drive'],
    workstreams:[
      {title:'Applicant pipeline & lease preparation',problem:'Approved applicants, roommates, and custom terms need to be organized before agreements can be prepared.',built:'Grouped roommates, matched units, deduplicated records, and gathered custom lease terms in a one-click action hub.',benefit:'Keeps the applicant handoff and lease preparation in one place.'},
      {title:'Relational data integration',problem:'Properties, units, tenants, and owners live in nested or separate ERP records that simple connectors struggle to join.',built:'Batch-fetched API datasets, mapped related entities in memory, and staged clean operational records in Google Sheets. Batching was designed around API rate limits and Apps Script quotas.',benefit:'Reduces repeated data transfer and keeps the same relationships available across operational tools.'},
      {title:'Lease lifecycle & Jira operations',problem:'Lease expiries, turnovers, and maintenance tasks are hard to prioritize across spreadsheets and boards.',built:'Synced leasing records with Jira, tracked unit stages from vacancy through renovation, eviction, and rental, and prioritized tasks using lease expiry dates. Maintenance requests create tasks with resident details and issue photos. Cards include rent and signed document links.',benefit:'Gives teams a visual task pipeline and surfaces approaching deadlines with less manual triage.'},
      {title:'Agreement generation & archival',problem:'Preparing agreements, requesting signatures, tracking completion, and filing PDFs creates a lengthy sequence of manual steps.',built:'Routed state-specific templates with custom lease terms, deposits, and pet clauses. A one-click action dispatches agreements to tenants and the landlord. Signature tracking triggers executed PDF archival into year/property folders in Drive, with links written to Sheets and attached to Jira.',benefit:'Connects agreement preparation, signature tracking, and document retrieval in one traceable workflow.'},
      {title:'Aging balances & fee breakdowns',problem:'Overdue rent and fee categories require repeated manual ledger checks before teams can understand outstanding balances.',built:'Synced overdue balances and late fees from the ERP ledger, separated charges into dynamic fee categories, and maintained staff audit logs in the operations hub.',benefit:'Provides a clearer view of aging balances and fee composition without repeatedly rebuilding reports.'}
    ],
    note:'Architecture based on my freelance implementation. Business benefits describe the workflows delivered.'
  },
  secres: {category:'AGENTIC AI / PERSONAL PROJECT',title:'SecRes',subtitle:'Deterministic Multi-Agent Plan-and-Execute Research System',problem:'How can a local-first research agent use small language models without depending on fragile model tool-calling behavior?',approach:'Separated LLM planning from deterministic execution loops. The system uses LangGraph for orchestration, Ollama for local models, FAISS for retrieval, and Streamlit for the interface.',details:['A plan-and-execute architecture separates reasoning from tool execution.','A security gateway uses Microsoft Presidio for PII redaction and Llama Guard to help screen unsafe inputs.','Research steps feed a synthesis workflow designed to keep the output grounded in retrieved information.'],metric:'Local-first reasoning. Deterministic execution.',stack:['Python','LangGraph','Ollama','FAISS','Streamlit','Presidio'],repo:'https://github.com/AdityaB1007/SecRes',note:'Architecture summarized from my resume. The project illustration is a conceptual workflow, not a screenshot of the app.'},
  voice: {category:'MACHINE LEARNING / PERSONAL PROJECT',title:'Fraudulent AI Voice Detection',subtitle:'A real-time pipeline for spoofed vs. bona fide audio.',problem:'Distinguish synthesized voice from genuine audio while keeping the inference pipeline suitable for real-time fraud detection use cases.',approach:'Engineered and selected audio features using ANOVA and Random Forest feature importance, then trained and optimized Random Forest and XGBoost models with cross-validation and hyperparameter tuning.',details:['Reduced feature redundancy to improve generalization.','Reached approximately 98% test accuracy and approximately 97% unseen/validation accuracy.','Designed a low-latency inference pipeline and Flask integration, tested with Postman.'],metric:'~97% unseen / validation accuracy',stack:['Python','Librosa','Random Forest','XGBoost','Flask','Postman'],note:'Results are reported in my resume on the project’s test and validation data. They are not a guarantee of performance on other audio sources. The waveform is illustrative.'},
  spotify: {category:'RECOMMENDER SYSTEMS / PERSONAL PROJECT',title:'SpotifyXplore',subtitle:'Hybrid music discovery across a 1M+ song dataset.',problem:'Combine personalized recommendations with fast similarity search and flexible metadata filtering for music discovery.',approach:'Combined Neural Collaborative Filtering and K-Means clustering, with a FAISS vector database for high-speed embedding retrieval. A FastAPI backend serves discovery endpoints.',details:['Used a dataset with more than one million songs.','Built metadata filtering, smart search, and similar-track endpoints.','Reported sub-millisecond embedding retrieval using FAISS.'],metric:'1M+ songs. Hybrid recommendations.',stack:['Python','PyTorch','FastAPI','FAISS','Scikit-learn','Pandas'],repo:'https://github.com/AdityaB1007/SpotifyXplore',note:'Dataset size and retrieval performance are reported in my resume. The record artwork is a conceptual illustration, not a product screenshot.'}
};
const projectDialog=document.querySelector('#project-dialog');
const briefDialog=document.querySelector('#brief-dialog');
let opener=null;
function openDialog(dialog,trigger){opener=trigger;dialog.showModal();document.body.classList.add('modal-open');}
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{
  const p=projects[button.dataset.project];
  document.querySelector('#project-detail').innerHTML=`<div class="eyebrow section-kicker">${p.category}</div><h2 id="project-title">${p.title}</h2><p>${p.subtitle}</p><strong class="metric">${p.metric}</strong>${p.architecture||''}<h3>The problem</h3><p>${p.problem}</p><h3>The approach</h3><p>${p.approach}</p><ul>${p.details.map(x=>`<li>${x}</li>`).join('')}</ul>${(p.workstreams||[]).map((w,i)=>`<section class="case-workstream"><div class="mono">WORKSTREAM 0${i+1}</div><h3>${w.title}</h3><p><strong>The problem:</strong> ${w.problem}</p><p><strong>What I built:</strong> ${w.built}</p><p class="case-benefit"><strong>Business benefit:</strong> ${w.benefit}</p></section>`).join('')}<div class="tags">${p.stack.map(x=>`<span>${x}</span>`).join('')}</div>${p.repo?`<a class="button primary" href="${p.repo}">Explore the source <span>↗</span></a>`:''}<p class="detail-note">${p.note}</p>`;
  openDialog(projectDialog,button);
}));
document.querySelectorAll('dialog').forEach(dialog=>{
  dialog.querySelector('.modal-close').addEventListener('click',()=>dialog.close());
  dialog.addEventListener('click',event=>{const rect=dialog.getBoundingClientRect();if(event.target===dialog&&(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom))dialog.close();});
  dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');opener?.focus();});
});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{
  document.querySelectorAll('[data-filter]').forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-pressed',String(active));});
  document.querySelectorAll('.project').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;});
}));
document.querySelector('#open-brief').addEventListener('click',event=>openDialog(briefDialog,event.currentTarget));
const briefForm=document.querySelector('#brief-form');
function getBrief(){const d=new FormData(briefForm);return `Hi Aditya, I'd like to discuss a project.\n\nProject / company: ${d.get('company').trim()}\nArea: ${d.get('service')}\n\nProblem and desired outcome:\n${d.get('problem').trim()}\n\nTimeline: ${d.get('timeline').trim()||'Open to discussion'}\n`;}
briefForm.addEventListener('submit',async event=>{event.preventDefault();try{await navigator.clipboard.writeText(getBrief());document.querySelector('#brief-status').textContent='Brief copied. Paste it into your LinkedIn message to Aditya.';}catch{document.querySelector('#brief-status').textContent='Clipboard access is unavailable. Download the brief instead.';}});
document.querySelector('#download-brief').addEventListener('click',()=>{if(!briefForm.reportValidity())return;const url=URL.createObjectURL(new Blob([getBrief()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ai-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#brief-status').textContent='Brief downloaded. You can share it in your LinkedIn message.';});
const wave=document.querySelector('.waveform');
for(let i=0;i<62;i++){const bar=document.createElement('i');bar.style.height=`${8+Math.abs(Math.sin(i*1.7)*Math.cos(i*.22))*100}px`;wave.append(bar);}
document.querySelector('#year').textContent=new Date().getFullYear();
